UPDATE public.master_plan_capability_library AS library
SET criteria = updates.criteria
FROM updates
WHERE library.code = updates.code;

DO $$
BEGIN
  IF (SELECT count(*) FROM public.master_plan_capability_library) <> 28 THEN
    RAISE EXCEPTION 'master_plan_capability_library_count_mismatch';
  END IF;
END $$;

COMMIT;
